  # --- 3a. Auto-Detect Baseline Survival ---
  base_age <- suppressWarnings(as.numeric(str_extract(BASELINE_TRAIT, "\\d+")))
  
  # 1. Guess the exact matching survival trait based on the zero-padded age
  target_surv_base <- paste0("Sur_", str_pad(base_age, 2, pad = "0"))
  
  # 2. Check if it exists. If not, find the closest one chronologically.
  if (target_surv_base %in% names(wide_data)) {
    BASELINE_SURV <- target_surv_base
  } else {
    surv_cols <- grep("(?i)^Sur_", names(wide_data), value = TRUE)
    if (length(surv_cols) > 0) {
      surv_ages <- suppressWarnings(as.numeric(str_extract(surv_cols, "\\d+")))
      closest_idx <- which.min(abs(surv_ages - base_age))
      BASELINE_SURV <- surv_cols[closest_idx]
      message(paste("  -> Exact survival not found. Auto-detected closest BASELINE_SURV:", BASELINE_SURV))
    } else {
      stop("CRITICAL ERROR: No survival traits found in dataset. Zombie filter cannot run.")
    }
  }
  
  # --- Data Loading & Zero Filtering ---
  working_data <- df_raw %>%
    select(Plot, Tree, 
           Base_Val = !!sym(BASELINE_TRAIT), Base_Surv = !!sym(BASELINE_SURV), 
           Test_Val = !!sym(TEST_TRAIT), Test_Surv = !!sym(TEST_SURV)) %>%
    filter(!str_detect(Plot, "(?i)Filler")) %>%
    mutate(
      Tree = as.numeric(Tree),
      Plot = as.character(Plot),
      # REPEATABLE ZERO FILTER: Treat '0' in measurement as NA (erroneous data)
      Base_Val = na_if(as.numeric(Base_Val), 0),
      Test_Val = na_if(as.numeric(Test_Val), 0)
    )
  
  # --- Auto-detect Interior ---
  test_trees_used <- unique(working_data %>% filter(!is.na(Test_Val)) %>% pull(Tree))
  layout_interior <- as.vector(get_grid_layout(PLOT_SIZE, interior_only = TRUE))
  
  is_test_interior <- FALSE
  if (PLOT_SIZE > 8 && length(test_trees_used) > 0 && all(test_trees_used %in% layout_interior)) {
    is_test_interior <- TRUE
    message(paste("Detected", TEST_TRAIT, "as an INTERIOR-ONLY measurement."))
  }
  
  layout_mat <- get_grid_layout(PLOT_SIZE, interior_only = is_test_interior)
  canonical_path <- get_traversal_path(layout_mat, "top_left", "horizontal", FALSE)
  
  base_age <- suppressWarnings(as.numeric(str_extract(BASELINE_TRAIT, "\\d+")))
  test_age <- suppressWarnings(as.numeric(str_extract(TEST_TRAIT, "\\d+")))
  
  # --- Permutation Generator ---
  if (PLOT_SIZE == 8) {
    combos <- tibble(Perm_ID = 1:2, start_corner = c("normal", "reversed"), direction = "horizontal", snake = FALSE)
  } else {
    combos <- expand_grid(start_corner = c("top_left", "bottom_left", "top_right", "bottom_right"), direction = c("horizontal", "vertical"), snake = c(FALSE, TRUE)) %>% mutate(Perm_ID = row_number())
  }
  
  plots <- unique(working_data$Plot)
  results_list <- list()
  
  message(paste("Testing", length(plots), "plots against", nrow(combos), "traversal permutations..."))
  
  for (p in plots) {
    plot_data <- working_data %>% filter(Plot == p)
    if(sum(!is.na(plot_data$Base_Val)) < 3 || sum(!is.na(plot_data$Test_Val)) < 3) next
    
    for (i in 1:nrow(combos)) {
      sc <- combos$start_corner[i]
      dir <- combos$direction[i]
      snk <- combos$snake[i]
      
      tested_path <- get_traversal_path(layout_mat, sc, dir, snk)
      translation_df <- tibble(Original_Tree = canonical_path, Mapped_Tree = tested_path)
      
      mapped_test <- plot_data %>% select(Tree, Test_Val, Test_Surv) %>% inner_join(translation_df, by = c("Tree" = "Original_Tree"))
      joined <- plot_data %>% select(Tree, Base_Val, Base_Surv) %>% left_join(mapped_test, by = c("Tree" = "Mapped_Tree"))
      
      mapped_test <- plot_data %>% select(Tree, Test_Val, Test_Surv) %>% inner_join(translation_df, by = c("Tree" = "Original_Tree"))
