    cat(sprintf("   -> %s corner, walking %s (Snake: %s)\n", toupper(dominant_fix$Best_Start), toupper(dominant_fix$Best_Dir), dominant_fix$Best_Snake))
    
    rebels <- recommendations %>% filter(str_detect(Action_Required, "FIX")) %>% filter(Best_Start != dominant_fix$Best_Start | Best_Dir != dominant_fix$Best_Dir | Best_Snake != dominant_fix$Best_Snake)
    if (nrow(rebels) > 0) {
      cat("3. PATTERN DEVIATIONS (Rebel Plots)\n")
      for(r in 1:nrow(rebels)) cat(sprintf("   - Plot %-4s: Assessor used %s, %s (Snake: %s)\n", rebels$Plot[r], toupper(rebels$Best_Start[r]), toupper(rebels$Best_Dir[r]), rebels$Best_Snake[r]))
    }
  } else {
