  }
  
  # --- Master Helper Export (DEFENSIVE) ---
  main_pipe_helper <- recommendations %>%
    filter(str_detect(Action_Required, "FIX")) %>%
    mutate(
      Trial_ID = basename(OUTPUT_DIR),
      Trait_ID = TEST_TRAIT, 
      Anchor_Used = BASELINE_TRAIT,
      Manual_Verification = "Pending",
      Best_Snake = as.character(Best_Snake), # Ensure logic doesn't crash bind_rows
      Plot = as.character(Plot)
    ) %>%
    select(Trial_ID, Trait_ID, Anchor_Used, Plot, Best_Start, Best_Dir, Best_Snake, Best_Cor, Normal_Cor)
  
  helper_path <- file.path(OUTPUT_DIR, "TRAVERSAL_HELPER_MASTER.csv")
  
  if (file.exists(helper_path)) {
    # Read everything as character to prevent type clashes
    existing_helper <- read_csv(helper_path, col_types = cols(.default = "c")) 
    combined_helper <- existing_helper %>% 
      filter(Trait_ID != TEST_TRAIT) %>% 
